//! A5 Go-escape check-site (`HYB-E3013`) — mutating method values and callback escapes to foreign Go calls.
use hy_check::{check_file, Verdict};
use hy_syntax::parse_file;

fn assert_e3013(src: &str) {
    let r = check_file(&parse_file("t.hy", src).expect("snippet parses"));
    assert_eq!(r.verdict, Verdict::Reject, "expected Reject for:\n{src}");
    assert_eq!(r.diagnostics.iter().map(|d| d.code.as_str()).collect::<Vec<_>>(), vec!["HYB-E3013"], "got {:?} for:\n{src}", r.diagnostics);
}
const PRE: &str = "import \"net/http\"\nimport \"time\"\ntype cb_fn = fn()\ntype box_alias = cb_box\nstruct decoy { n int }\nstruct stats { n int }\nstruct wrap { s stats }\nstruct holder { m map[string]int }\nstruct slice_holder { xs []int }\nstruct cb_box {\n    r fn()\n    w fn()\n}\nstruct outer_box { bx cb_box }\nfn _use_pkgs() {\n    _ = time.second\n    http.handle_func(\"/k\", fn() {})\n}\nfn noop() {}\nfn (d *decoy) incr() { _ = d.n }\nfn bump(s *stats) { s.n++ }\nfn run_local(f fn()) { f() }\nfn run_box_w(bx cb_box) { bx.w() }\nfn run_aliased(f fn()) {\n    g := f\n    g()\n}\nfn run_via_slice(f fn()) {\n    arr := []fn(){f}\n    arr[0]()\n}\nfn (s *stats) incr() { s.n++ }\nfn (s *stats) report() { _ = s.n }\nfn (s *stats) via_method() { s.incr() }\nfn (s *stats) via_fn() { bump(s) }\nfn (s *stats) incr_via_closure() {\n    f := fn() { s.n = s.n + 1 }\n    f()\n}\nfn (h holder) stomp() { h.m[\"k\"] = 1 }\nfn (h slice_holder) set() { h.xs[0] = 7 }\nfn (sh slice_holder) write0() { sh.xs[0] = 99 }\nfn make_cb(s *stats) fn() { return s.incr }\nfn make_named(s *stats) (cb cb_fn) {\n    cb = s.incr\n    return\n}\nfn passthru_cb(f fn()) fn() { return f }\nfn make_box(s *stats) cb_box { return cb_box{r: s.report, w: s.incr} }\nfn pair_mut_second(s *stats) (int, cb_fn) { return 1, s.incr }\nfn pair_named_second(s *stats) (ok int, cb cb_fn) {\n    ok = 1\n    cb = s.incr\n    return\n}\nfn invoke_via_slice(p *stats) {\n    arr := []fn(){p.incr}\n    if true {\n        p := stats{n: 1}\n        _ = p\n        arr[0]()\n    }\n}\nfn invoke_via_mval(p *stats) {\n    f := p.incr\n    if true {\n        p := stats{n: 1}\n        _ = p\n        f()\n    }\n}\nfn invoke_via_local_fn(p *stats) {\n    g := fn() { p.n = 2 }\n    if true {\n        p := stats{n: 1}\n        _ = p\n        g()\n    }\n}";

#[test]
fn direct_aliased_container_and_returned_method_values_reject() {
    for body in [
        "s := stats{n: 0}\nhttp.handle_func(\"/a\", s.incr)\n_ = s", "s := stats{n: 0}\nhttp.handle_func(\"/a\", (&s).incr)", "s := stats{n: 0}\np := &s\nhttp.handle_func(\"/a\", p.incr)", "w := wrap{s: stats{n: 0}}\nhttp.handle_func(\"/a\", w.s.incr)\n_ = w", "s := stats{n: 0}\nmux := http.new_serve_mux()\nmux.handle(\"/x\", http.handler(s.incr))\n_ = s", "h := holder{m: map[string]int{\"k\": 0}}\nhttp.handle_func(\"/a\", h.stomp)\n_ = h", "h := slice_holder{xs: []int{0}}\nhttp.handle_func(\"/a\", h.set)\n_ = h", "st := set[int]{}\nhttp.handle_func(\"/a\", st.clear)\n_ = st", "s := stats{n: 0}\ncb := s.incr\ncb2 := cb\nhttp.handle_func(\"/a\", cb2)\n_ = s", "s := stats{n: 0}\ncb := s.report\nif s.n == 0 { cb = s.incr }\nhttp.handle_func(\"/a\", cb)\n_ = s", "s := stats{n: 0}\ncb := s.incr\nif s.n > 0 { cb = s.report }\nhttp.handle_func(\"/a\", cb)\n_ = s", "s := stats{n: 0}\nfor cb in []fn(){s.incr} { http.handle_func(\"/a\", cb) }\n_ = s",
        "s := stats{n: 0}\ncb := s.report\nfor i in 0..2 {\n_ = i\nhttp.handle_func(\"/a\", cb)\ncb = s.incr\n}\n_ = s", "s := stats{n: 0}\ncbs := []fn(){s.report, s.incr}\nhttp.handle_func(\"/a\", cbs[1])\n_ = s", "s := stats{n: 0}\ni := 0\ncbs := []fn(){s.report, s.incr}\nhttp.handle_func(\"/a\", cbs[i])\n_ = s", "s := stats{n: 0}\ncbs := append([]fn(){s.report}, s.incr)\nhttp.handle_func(\"/a\", cbs[0])\n_ = s", "s := stats{n: 0}\nmp := map[string]fn(){\"r\": s.report, \"w\": s.incr}\nhttp.handle_func(\"/a\", mp[\"w\"])\n_ = s", "s := stats{n: 0}\nbx := cb_box{r: s.report, w: s.incr}\nhttp.handle_func(\"/a\", bx.w)\n_ = s", "s := stats{n: 0}\nhttp.handle_func(\"/a\", cb_fn(s.incr))\n_ = s", "s := stats{n: 0}\nhttp.handle_func(\"/a\", s.via_method)\n_ = s", "s := stats{n: 0}\nhttp.handle_func(\"/a\", s.via_fn)\n_ = s", "s := stats{n: 0}\nhttp.handle_func(\"/a\", make_cb(&s))", "s := stats{n: 0}\nhttp.handle_func(\"/a\", make_named(&s))",
    ] { assert_e3013(&format!("{PRE}\nfn main() {{\n{body}\n}}\n")); }
}
#[test]
fn closure_tuple_lexical_scope_projection_and_rebind_escapes_reject() {
    for body in [
        "s := stats{n: 0}\n_ = time.after_func(0, fn() {\nf := s.incr\nf()\n})\n_ = s", "s := stats{n: 0}\ncb := s.incr\n_ = time.after_func(0, fn() { cb() })\n_ = s", "s := stats{n: 0}\nouter := fn() {\nf := s.incr\nf()\n}\n_ = time.after_func(0, outer)\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, (fn() fn() { return s.incr })())\n_ = s", "s := stats{n: 0}\nmk := fn() fn() { return s.incr }\n_ = time.after_func(0, mk())\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, s.incr_via_closure)\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() { s.incr() })\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() { bump(&s) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() { run_local(s.incr) })\n_ = s", "s := stats{n: 0}\n_, cb := pair_mut_second(&s)\n_ = time.after_func(0, cb)", "s := stats{n: 0}\n_, cb := pair_named_second(&s)\n_ = time.after_func(0, cb)", "s := stats{n: 0}\nok := 0\ncb := s.report\nok, cb = pair_mut_second(&s)\n_ = ok\n_ = time.after_func(0, cb)", "s := stats{n: 0}\n_ = time.after_func(0, passthru_cb(s.incr))\n_ = s", "if false {\nx := decoy{n: 0}\n_ = x\n}\nx := stats{n: 0}\ncb := x.incr\n_ = time.after_func(0, cb)\n_ = x",
        "s := stats{n: 0}\nopt := some(s.incr)\nmatch opt {\nsome(cb): { _ = time.after_func(0, cb) }\nnone: {}\n}\n_ = s", "s := stats{n: 0}\nopt := some(&s)\nmatch opt {\nsome(p): {\ncb := p.incr\n_ = time.after_func(0, cb)\n}\nnone: {}\n}", "s := stats{n: 0}\nptrs := []*stats{&s}\nfor _, p in ptrs {\ncb := p.incr\n_ = time.after_func(0, cb)\n}", "ch := make(chan holder, 1)\nselect {\nh := <-ch: {\ncb := h.stomp\n_ = time.after_func(0, cb)\n}\ndefault: {}\n}", "s := stats{n: 0}\nrun := fn(p *stats) {\ncb := p.incr\n_ = time.after_func(0, cb)\n}\nrun(&s)", "s := stats{n: 0}\nfor idx, cb in []fn(){s.incr} {\n_ = idx\n_ = time.after_func(0, cb)\n}\n_ = s", "s := stats{n: 0}\nmp := map[string]fn(){\"w\": s.incr}\nfor _, cb in mp { _ = time.after_func(0, cb) }\n_ = s", "s := stats{n: 0}\nob := outer_box{bx: cb_box{r: s.report, w: s.incr}}\n_ = time.after_func(0, ob.bx.w)\n_ = s", "s := stats{n: 0}\nxs := []cb_box{cb_box{r: s.report, w: s.incr}}\n_ = time.after_func(0, xs[0].w)\n_ = s", "s := stats{n: 0}\nbx := make_box(&s)\n_ = time.after_func(0, bx.w)", "s := stats{n: 0}\nbx := box_alias(cb_box{r: s.report, w: s.incr})\n_ = time.after_func(0, bx.w)\n_ = s", "s := stats{n: 0}\ncb := s.report\nset_it := fn() { cb = s.incr }\nset_it()\n_ = time.after_func(0, cb)\n_ = s", "s := stats{n: 0}\ncb := s.report\nrun := fn() { _ = time.after_func(0, cb) }\ncb = s.incr\nrun()\n_ = s", "s := stats{n: 0}\ncb := s.report\nrun := fn() { _ = time.after_func(0, cb) }\ncb = s.incr\nrun()\ncb = s.report\n_ = s",
        "s := stats{n: 0}\ncb := s.report\nrun := fn() { _ = time.after_func(0, cb) }\nset_it := fn() {\ncb = s.incr\nrun()\ncb = s.report\n}\nset_it()\n_ = s", "s := stats{n: 0}\ncb := s.report\nrun := fn() { _ = time.after_func(0, cb) }\ny, cb := 1, s.incr\n_ = y\nrun()\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\nf := s.incr\ns := stats{n: 1}\n_ = s\nf()\n})\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\narr := []fn(){s.incr}\ns := stats{n: 1}\n_ = s\narr[0]()\n})\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\ng := fn() { s.n = 2 }\ns := stats{n: 1}\n_ = s\ng()\n})\n_ = s", "s := stats{n: 0}\nc0 := s.incr\nc1 := c0\nc2 := c1\nc3 := c2\nc4 := c3\nc5 := c4\nc6 := c5\n_ = time.after_func(0, c6)\n_ = s", "var f fn() = noop\nif true {\ns2 := stats{n: 0}\nf = s2.incr\n}\n_ = time.after_func(0, fn() { f() })\nf()", "shared := []int{1, 2}\nvar f fn() = noop\nif true {\nsh := slice_holder{xs: shared}\nf = sh.set\n}\n_ = time.after_func(0, fn() { f() })\nshared[0] = 9", "var f fn() = noop\nrun := fn() { f() }\nif true {\ns2 := stats{n: 0}\nf = s2.incr\n}\n_ = time.after_func(0, run)\nf()", "var f fn() = noop\nif true {\ns2 := stats{n: 0}\nf = fn() { s2.n = s2.n + 1 }\n}\n_ = time.after_func(0, fn() { f() })\nf()", "s := stats{n: 0}\n_ = time.after_func(0, fn() { invoke_via_slice(&s) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() { invoke_via_mval(&s) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() { invoke_via_local_fn(&s) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\ninner := fn() {\nf := s.incr\ns := stats{n: 2}\n_ = s\nf()\n}\ninner()\n})",
        "if x := (stats{n: 0}); true {\ncb := x.incr\n_ = time.after_func(0, cb)\n}", "s2 := stats{n: 0}\n_ = time.after_func(0, fn() {\nls := stats{n: 1}\np := &ls\nif true { p = &s2 }\np.n = 99\n})", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\nvar f fn() = noop\nif true {\np := &s\nf = p.incr\n}\nf()\n})", "var make_f fn() fn() = fn() fn() { return noop }\nif true {\ns2 := stats{n: 0}\nmake_f = fn() fn() { return s2.incr }\n}\n_ = time.after_func(0, fn() {\nf := make_f()\nf()\n})", "s := stats{n: 0}\nmk := fn() fn() {\nif false {\ns := stats{n: 1}\n_ = s\n}\nreturn s.incr\n}\n_ = time.after_func(0, mk())", "shared := []int{1, 2}\nmk := fn() fn() {\nsh := slice_holder{xs: shared}\nreturn sh.set\n}\n_ = time.after_func(0, mk())\nshared[0] = 9", "shared := []int{1, 2}\n_ = time.after_func(0, fn() {\nvar f fn() = noop\nif true {\nsh := slice_holder{xs: shared}\nf = sh.set\n}\nf()\n})\nshared[0] = 9", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\nls := stats{n: 1}\np := &ls\ng := fn() { p.n = 99 }\np = &s\ng()\n})", "shared := []int{1, 2, 3}\n_ = time.after_func(0, fn() {\nsh := slice_holder{xs: []int{0}}\ng := fn() { sh.xs[0] = 99 }\nsh = slice_holder{xs: shared}\ng()\n})\nshared[0] = 42", "shared := []int{1, 2, 3}\n_ = time.after_func(0, fn() {\nsh := slice_holder{xs: []int{0}}\nmk := fn() fn() { return sh.write0 }\nsh = slice_holder{xs: shared}\nf := mk()\nf()\n})\nshared[0] = 42", "shared := []int{1, 2, 3}\n_ = time.after_func(0, fn() {\nsh := slice_holder{xs: []int{0}}\ng := fn() { sh.write0() }\nsh.xs = shared\ng()\n})\nshared[0] = 42", "s := stats{n: 0}\n_ = time.after_func(0, fn() { run_aliased(s.incr) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() { run_via_slice(s.incr) })", "s := stats{n: 0}\n_ = time.after_func(0, fn() { run_box_w(cb_box{r: s.report, w: s.incr}) })",
    ] { assert_e3013(&format!("{PRE}\nfn main() {{\n{body}\n}}\n")); }
}
